import asyncio; from datetime import date; from decimal import Decimal; from uuid import uuid4; from sqlalchemy import select; from sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker; from src.extraction import BankStatementStatus, DocumentType, ExtractedPositionFact, ExtractionMethod, SourceProvenance, StatementEvidenceType, StatementExtractionResult, StatementSourceType, TransactionDirection, UploadedDocument; from src.extraction.extension.brokerage_positions import BrokeragePositionImportService, _asset_type, _clean_decimal, _parse_date, _payload_currency, _statement_date, detect_broker, parse_brokerage_positions; from src.extraction.extension.brokerage_statement_payload import _brokerage_payload_from_statement; from src.extraction.orm.layer2 import AssetType, AtomicPosition, AtomicTransaction; from src.extraction.orm.layer3 import ManagedPosition; from src.extraction.orm.statement_summary import StatementSummary; from src.ledger import Account, AccountType; from src.portfolio import PositionService; from src.schemas.portfolio import BrokerageImportRequest, BrokerageImportResponse
async def _seed_statement(db, user_id, *, file_hash, file_path, original_filename, institution='Moomoo', status=BankStatementStatus.PARSED, currency='SGD', extraction_metadata=None, transactions=None, **summary_kwargs) -> StatementSummary:
    document = UploadedDocument(user_id=user_id, file_path=file_path, file_hash=file_hash, original_filename=original_filename, document_type=DocumentType.BANK_STATEMENT, extraction_metadata=extraction_metadata); db.add(document); await db.flush(); statement = StatementSummary(user_id=user_id, uploaded_document_id=document.id, file_hash=file_hash, institution=institution, currency=currency, status=status, extraction_metadata=extraction_metadata, **summary_kwargs); db.add(statement); await db.flush()
    for txn_spec in transactions or []: txn = AtomicTransaction(user_id=user_id, txn_date=txn_spec['txn_date'], description=txn_spec['description'], amount=txn_spec['amount'], direction=txn_spec['direction'], reference=txn_spec.get('reference'), currency=txn_spec.get('currency', currency), dedup_hash=uuid4().hex + uuid4().hex, source_documents=[{'doc_id': str(document.id), 'doc_type': DocumentType.BANK_STATEMENT.value}]); db.add(txn)
    await db.flush(); return statement
