async def test_import_interactive_brokers_positions_idempotently_reconciles(db, test_user): 'AC-portfolio.brokerage-import.3 AC17.4.3'; service = BrokeragePositionImportService(); payload = {'institution': 'Interactive Brokers', 'statement': {'period_end': '2026-05-18', 'currency': 'USD'}, 'positions': [{'symbol': 'AAPL', 'quantity': '10', 'market_value': '1900.25', 'currency': 'USD', 'asset_type': 'stock', 'sector': 'Technology', 'geography': 'US'}]}; first = await service.import_positions(db, user_id=test_user.id, payload=payload, source_document_id='doc-ibkr'); second = await service.import_positions(db, user_id=test_user.id, payload=payload, source_document_id='doc-ibkr'); await db.commit(); assert first.created_atomic_positions == 1; assert first.reconcile_created == 1; assert second.created_atomic_positions == 0; assert second.reconcile_created == 0; atomic_rows = (await db.execute(select(AtomicPosition).where(AtomicPosition.user_id == test_user.id))).scalars().all(); assert len(atomic_rows) == 1; assert atomic_rows[0].asset_identifier == 'AAPL'; assert atomic_rows[0].sector == 'Technology'; managed_rows = (await db.execute(select(ManagedPosition).where(ManagedPosition.user_id == test_user.id))).scalars().all(); assert len(managed_rows) == 1; assert managed_rows[0].asset_identifier == 'AAPL'; assert managed_rows[0].quantity == Decimal('10')
