async def test_AC17_4_8_brokerage_import_survives_concurrent_auto_and_manual_import(db_engine, test_user):
    'AC-portfolio.brokerage-import.6 AC17.4.8'; service = BrokeragePositionImportService(); payload = {'institution': 'Moomoo', 'statement': {'period_end': '2026-06-30', 'currency': 'SGD'}, 'positions': [{'symbol': 'Fullerton SGD Money Market Fund', 'quantity': '1', 'market_value': '1250.50', 'currency': 'SGD', 'asset_type': 'money_market'}]}; sessionmaker = async_sessionmaker(db_engine, class_=AsyncSession, expire_on_commit=False)
    async with sessionmaker() as auto_session, sessionmaker() as manual_session: auto_result = await service.import_positions(auto_session, user_id=test_user.id, payload=payload, source_document_id='auto-parse-doc', reconcile=False); manual_task = asyncio.create_task(service.import_positions(manual_session, user_id=test_user.id, payload=payload, source_document_id='manual-import-doc', reconcile=False)); await asyncio.sleep(0.2); await auto_session.commit(); manual_result = await asyncio.wait_for(manual_task, timeout=5); await manual_session.commit()
    async with sessionmaker() as verify_session: positions = (await verify_session.execute(select(AtomicPosition).where(AtomicPosition.user_id == test_user.id))).scalars().all()
    assert auto_result.created_atomic_positions == 1; assert manual_result.created_atomic_positions == 0; assert manual_result.existing_atomic_positions == 1; assert len(positions) == 1; assert positions[0].asset_identifier == 'Fullerton SGD Money Market Fund'
